  CONSTRAINT "team_uq_0" UNIQUE ("id", "plant_id"),
  CONSTRAINT "team_ck_0" CHECK (revision >= 1),
  CONSTRAINT "team_ck_1" CHECK (state in ('forming', 'active', 'paused')),
  CONSTRAINT "team_ck_2" CHECK (leader_source in ('explicit', 'role_derived', 'legacy')),
  CONSTRAINT "team_ck_3" CHECK (responsibility_offer in ('accepted', 'declined')),
  CONSTRAINT "team_ck_4" CHECK ((leader_person_id is null) = (leader_source is null)),
  CONSTRAINT "team_ck_5" CHECK ((responsibility_offer is null) = (responsibility_offer_version_id is null))
);

CREATE UNIQUE INDEX "team_uq_1" ON "team" ("plant_id", "template_key") WHERE template_key is not null;

CREATE TABLE "team_role" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "plant_id" uuid NOT NULL,
  "team_id" uuid NOT NULL,
  "name" text NOT NULL,
  "description" text,
  "leadership" boolean NOT NULL,
  "time_commitment" text,
  "desired_skills" text,
  "sort_order" integer NOT NULL,
  "template_key" text,
  "retired_at" timestamptz,
  "responsibility_key" text,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "team_role_uq_0" UNIQUE ("id", "plant_id"),
  CONSTRAINT "team_role_ck_0" CHECK (revision >= 1),
  CONSTRAINT "team_role_ck_1" CHECK (responsibility_key in ('worship', 'children', 'assimilation', 'small_groups', 'administration_finance', 'facilities', 'promotion', 'technology', 'prayer'))
);

CREATE UNIQUE INDEX "team_role_uq_1" ON "team_role" ("team_id", "template_key") WHERE template_key is not null;

CREATE TABLE "team_tenure" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
