CREATE UNIQUE INDEX "team_tenure_uq_1" ON "team_tenure" ("role_id") WHERE ended_on is null;

CREATE TABLE "responsibility" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "plant_id" uuid NOT NULL,
  "team_id" uuid NOT NULL,
  "source_version_id" uuid NOT NULL,
  "source_line" text NOT NULL,
  "text" text NOT NULL,
  "sort_order" integer NOT NULL,
  "completed_on" date,
  "removed_at" timestamptz,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "responsibility_uq_0" UNIQUE ("id", "plant_id"),
  CONSTRAINT "responsibility_uq_1" UNIQUE ("team_id", "source_version_id", "source_line"),
  CONSTRAINT "responsibility_ck_0" CHECK (revision >= 1)
);

CREATE TABLE "training_program" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "plant_id" uuid NOT NULL,
  "team_id" uuid,
  "name" text NOT NULL,
  "description" text,
  "required" boolean NOT NULL,
  "archived_at" timestamptz,
  "current_version_id" uuid,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "training_program_uq_0" UNIQUE ("id", "plant_id"),
  CONSTRAINT "training_program_ck_0" CHECK (revision >= 1)
);

CREATE TABLE "training_version" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "plant_id" uuid NOT NULL,
  "program_id" uuid NOT NULL,
  "version_number" integer NOT NULL,
  "source_hash" text NOT NULL,
  "compatible_prior_id" uuid,
  PRIMARY KEY ("id"),
