  CONSTRAINT "training_version_uq_1" UNIQUE ("program_id", "version_number"),
  CONSTRAINT "training_version_uq_2" UNIQUE ("id", "program_id"),
  CONSTRAINT "training_version_ck_0" CHECK (compatible_prior_id is null or compatible_prior_id <> id)
);

CREATE TABLE "training_requirement" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "plant_id" uuid NOT NULL,
  "version_id" uuid NOT NULL,
  "requirement_key" text NOT NULL,
  "kind" text NOT NULL,
  "description" text NOT NULL,
  "article_id" uuid,
  "source_revision_id" uuid,
  "minimum_fraction" numeric,
  PRIMARY KEY ("id"),
  CONSTRAINT "training_requirement_uq_0" UNIQUE ("id", "plant_id"),
  CONSTRAINT "training_requirement_uq_1" UNIQUE ("version_id", "requirement_key"),
  CONSTRAINT "training_requirement_ck_0" CHECK (kind in ('human', 'reading')),
  CONSTRAINT "training_requirement_ck_1" CHECK ((kind = 'reading') = (article_id is not null and source_revision_id is not null and minimum_fraction is not null))
);

CREATE TABLE "training_assignment" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "plant_id" uuid NOT NULL,
  "person_id" uuid NOT NULL,
  "program_id" uuid NOT NULL,
  "version_id" uuid NOT NULL,
  "assigned_on" date NOT NULL,
  "ended_on" date,
  "selection_operation_id" uuid NOT NULL,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "training_assignment_uq_0" UNIQUE ("id", "plant_id"),
  CONSTRAINT "training_assignment_ck_0" CHECK (revision >= 1)
);

CREATE UNIQUE INDEX "training_assignment_uq_1" ON "training_assignment" ("person_id", "program_id") WHERE ended_on is null;

CREATE TABLE "training_credit" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "plant_id" uuid NOT NULL,
  "person_id" uuid NOT NULL,
  "version_id" uuid NOT NULL,
  "assignment_id" uuid,
  "completed_on" date NOT NULL,
  "recorded_at" timestamptz NOT NULL,
  "notes" text,
  "revoked_at" timestamptz,
  "prior_credit_id" uuid,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "training_credit_uq_0" UNIQUE ("id", "plant_id"),
  CONSTRAINT "training_credit_ck_0" CHECK (revision >= 1)
);

CREATE UNIQUE INDEX "training_credit_uq_1" ON "training_credit" ("person_id", "version_id") WHERE revoked_at is null;

CREATE TABLE "venue" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "plant_id" uuid NOT NULL,
  "name" text NOT NULL,
  "address" text NOT NULL,
  "contact_name" text,
  "phone" text,
  "email" text,
  "cost_description" text,
  "capacity" integer,
  "notes" text,
  "archived_at" timestamptz,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "venue_uq_0" UNIQUE ("id", "plant_id"),
  CONSTRAINT "venue_ck_0" CHECK (revision >= 1),
  CONSTRAINT "venue_ck_1" CHECK (capacity is null or capacity >= 1)
);

CREATE TABLE "meeting" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "plant_id" uuid NOT NULL,
  "type" text NOT NULL,
  "subtype" text,
  "title" text NOT NULL,
  "notes" text,
  "creator_id" uuid,
  "local_date" date NOT NULL,
  "local_time" time NOT NULL,
  "timezone" text NOT NULL,
  "starts_at" timestamptz NOT NULL,
  "resolver_version" text NOT NULL,
  "actual_occurrence_at" timestamptz,
  "occurrence_voided_at" timestamptz,
  "team_id" uuid,
  "venue_id" uuid,
  "venue_name" text,
  "venue_address" text,
  "vision_number" integer,
  "reference_version_id" uuid,
  "status" text NOT NULL,
  "attendance_revision" bigint NOT NULL,
  "finalized_revision" bigint,
  "finalized_at" timestamptz,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "meeting_uq_0" UNIQUE ("id", "plant_id"),
  CONSTRAINT "meeting_ck_0" CHECK (revision >= 1),
  CONSTRAINT "meeting_ck_1" CHECK (type in ('vision_meeting', 'orientation', 'team_meeting', 'prelaunch_practice')),
  CONSTRAINT "meeting_ck_2" CHECK (subtype in ('regular', 'training', 'planning', 'special', 'rehearsal')),
  CONSTRAINT "meeting_ck_3" CHECK (status in ('planning', 'ready', 'in_progress', 'completed', 'cancelled')),
  CONSTRAINT "meeting_ck_4" CHECK ((type = 'team_meeting') = (team_id is not null)),
  CONSTRAINT "meeting_ck_5" CHECK (type = 'vision_meeting' or vision_number is null),
  CONSTRAINT "meeting_ck_6" CHECK (type <> 'prelaunch_practice' or status <> 'completed' or actual_occurrence_at is not null)
);

CREATE UNIQUE INDEX "meeting_uq_1" ON "meeting" ("plant_id", "vision_number") WHERE vision_number is not null;

CREATE TABLE "meeting_item" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "plant_id" uuid NOT NULL,
  "meeting_id" uuid NOT NULL,
  "kind" text NOT NULL,
  "source_key" text,
  "position" integer NOT NULL,
  "title" text NOT NULL,
  "duration_minutes" integer,
  "category" text,
  "assigned_person_id" uuid,
  "checked" boolean,
  "notes" text,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "meeting_item_uq_0" UNIQUE ("id", "plant_id"),
  CONSTRAINT "meeting_item_uq_1" UNIQUE ("meeting_id", "kind", "position"),
  CONSTRAINT "meeting_item_ck_0" CHECK (revision >= 1),
  CONSTRAINT "meeting_item_ck_1" CHECK (kind in ('agenda', 'kit')),
  CONSTRAINT "meeting_item_ck_2" CHECK (category in ('essential', 'materials', 'setup', 'av', 'organization')),
  CONSTRAINT "meeting_item_ck_3" CHECK ((kind = 'agenda' and duration_minutes between 0 and 600 and category is null and checked is null and assigned_person_id is null) or (kind = 'kit' and duration_minutes is null and category is not null and checked is not null)),
  CONSTRAINT "meeting_item_ck_4" CHECK (length(btrim(title)) between 1 and 120)
);

CREATE UNIQUE INDEX "meeting_item_uq_2" ON "meeting_item" ("meeting_id", "source_key") WHERE source_key is not null;

CREATE TABLE "participation" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "plant_id" uuid NOT NULL,
  "meeting_id" uuid NOT NULL,
  "person_id" uuid NOT NULL,
  "inviter_person_id" uuid,
  "roster_member" boolean NOT NULL,
  "rsvp" text,
  "rsvp_at" timestamptz,
  "presence" text NOT NULL,
  "actual_occurrence_at" timestamptz,
  "classification" text,
  "classification_stage" text,
  "classification_person_revision" bigint,
  "classification_as_of" timestamptz,
  "prior_vision_id" uuid,
  "card_response" text,
  "card_notes" text,
  "card_recorded_at" timestamptz,
  "card_author_id" uuid,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "participation_uq_0" UNIQUE ("id", "plant_id"),
  CONSTRAINT "participation_uq_1" UNIQUE ("meeting_id", "person_id"),
  CONSTRAINT "participation_ck_0" CHECK (revision >= 1),
  CONSTRAINT "participation_ck_1" CHECK (rsvp in ('pending', 'confirmed', 'declined')),
  CONSTRAINT "participation_ck_2" CHECK (presence in ('attended', 'absent', 'excused')),
  CONSTRAINT "participation_ck_3" CHECK (classification in ('first_time', 'returning', 'core_group')),
  CONSTRAINT "participation_ck_4" CHECK (card_response in ('ready_commit', 'interested', 'prayer_request', 'stay_informed', 'not_interested')),
  CONSTRAINT "participation_ck_5" CHECK (inviter_person_id is null or inviter_person_id <> person_id),
  CONSTRAINT "participation_ck_6" CHECK ((card_response is null) = (card_recorded_at is null))
);

CREATE TABLE "rsvp_proof" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "plant_id" uuid NOT NULL,
  "participation_id" uuid NOT NULL,
  "token_hash" text NOT NULL,
  "expires_at" timestamptz NOT NULL,
  "state" text NOT NULL,
  "answered_at" timestamptz,
  PRIMARY KEY ("id"),
  CONSTRAINT "rsvp_proof_uq_0" UNIQUE ("id", "plant_id"),
  CONSTRAINT "rsvp_proof_uq_1" UNIQUE ("token_hash"),
  CONSTRAINT "rsvp_proof_ck_0" CHECK (state in ('pending', 'answered', 'revoked', 'superseded', 'expired'))
);

CREATE UNIQUE INDEX "rsvp_proof_uq_2" ON "rsvp_proof" ("participation_id") WHERE state = 'pending';

CREATE TABLE "meeting_evaluation" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "plant_id" uuid NOT NULL,
  "meeting_id" uuid NOT NULL,
  "evaluated_on" date NOT NULL,
  "recorded_at" timestamptz NOT NULL,
  "reference_version_id" uuid NOT NULL,
  "attendance" integer NOT NULL,
  "location" integer NOT NULL,
  "logistics" integer NOT NULL,
  "agenda" integer NOT NULL,
  "vibe" integer NOT NULL,
  "message" integer NOT NULL,
  "close" integer NOT NULL,
  "next_steps" integer NOT NULL,
  "notes" text,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "meeting_evaluation_uq_0" UNIQUE ("id", "plant_id"),
  CONSTRAINT "meeting_evaluation_uq_1" UNIQUE ("meeting_id"),
  CONSTRAINT "meeting_evaluation_ck_0" CHECK (revision >= 1),
  CONSTRAINT "meeting_evaluation_ck_1" CHECK (attendance between 1 and 5),
  CONSTRAINT "meeting_evaluation_ck_2" CHECK (location between 1 and 5),
  CONSTRAINT "meeting_evaluation_ck_3" CHECK (logistics between 1 and 5),
  CONSTRAINT "meeting_evaluation_ck_4" CHECK (agenda between 1 and 5),
  CONSTRAINT "meeting_evaluation_ck_5" CHECK (vibe between 1 and 5),
  CONSTRAINT "meeting_evaluation_ck_6" CHECK (message between 1 and 5),
  CONSTRAINT "meeting_evaluation_ck_7" CHECK (close between 1 and 5),
  CONSTRAINT "meeting_evaluation_ck_8" CHECK (next_steps between 1 and 5)
);

CREATE TABLE "task" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "plant_id" uuid NOT NULL,
  "title" text NOT NULL,
  "description" text,
  "category" text NOT NULL,
  "priority" text NOT NULL,
  "status" text NOT NULL,
  "creator_id" uuid,
  "created_at" timestamptz NOT NULL,
  "assignee_id" uuid,
  "due_kind" text NOT NULL,
  "due_date" date,
  "due_time" time,
  "timezone" text,
  "due_at" timestamptz,
  "resolver_version" text,
  "person_id" uuid,
  "meeting_id" uuid,
  "team_id" uuid,
  "launch_id" uuid,
  "parent_id" uuid,
  "position" integer,
  "series_id" uuid,
  "occurrence_key" text,
  "predecessor_id" uuid,
  "obligation_id" uuid,
  "completed_at" timestamptz,
  "deleted_at" timestamptz,
  "source_template_id" uuid,
  "import_operation_id" uuid,
  "milestone_id" uuid,
  "seed_key" text,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "task_uq_0" UNIQUE ("id", "plant_id"),
  CONSTRAINT "task_ck_0" CHECK (revision >= 1),
  CONSTRAINT "task_ck_1" CHECK (status in ('not_started', 'in_progress', 'blocked', 'complete', 'no_longer_needed')),
  CONSTRAINT "task_ck_2" CHECK (priority in ('low', 'medium', 'high', 'urgent')),
  CONSTRAINT "task_ck_3" CHECK (due_kind in ('undated', 'date_only', 'timed')),
  CONSTRAINT "task_ck_4" CHECK (num_nonnulls(person_id, meeting_id, team_id, launch_id) <= 1),
  CONSTRAINT "task_ck_5" CHECK (parent_id is null or parent_id <> id),
  CONSTRAINT "task_ck_6" CHECK (parent_id is null or (due_kind = 'undated' and series_id is null and occurrence_key is null and predecessor_id is null and obligation_id is null and num_nonnulls(person_id,meeting_id,team_id,launch_id) = 0)),
  CONSTRAINT "task_ck_7" CHECK ((due_kind = 'undated' and num_nonnulls(due_date,due_time,timezone,due_at,resolver_version) = 0) or (due_kind = 'date_only' and due_date is not null and num_nonnulls(due_time,timezone,due_at,resolver_version) = 0) or (due_kind = 'timed' and num_nonnulls(due_date,due_time,timezone,due_at,resolver_version) = 5)),
  CONSTRAINT "task_ck_8" CHECK ((status = 'complete') = (completed_at is not null)),
  CONSTRAINT "task_ck_9" CHECK (category in ('administrative', 'vision_meeting', 'follow_up', 'general', 'ministry_team', 'launch_prep', 'training', 'promotion', 'recurring')),
  CONSTRAINT "task_ck_10" CHECK (launch_id is null or launch_id = plant_id)
);

CREATE UNIQUE INDEX "task_uq_1" ON "task" ("series_id", "occurrence_key") WHERE series_id is not null;

CREATE UNIQUE INDEX "task_uq_2" ON "task" ("predecessor_id") WHERE predecessor_id is not null;

CREATE UNIQUE INDEX "task_uq_3" ON "task" ("series_id") WHERE series_id is not null and deleted_at is null and status not in ('complete','no_longer_needed');

CREATE UNIQUE INDEX "task_uq_4" ON "task" ("obligation_id") WHERE obligation_id is not null and deleted_at is null;

CREATE UNIQUE INDEX "task_uq_5" ON "task" ("milestone_id", "seed_key") WHERE seed_key is not null;

CREATE TABLE "task_dependency" (
  "plant_id" uuid NOT NULL,
  "task_id" uuid NOT NULL,
  "prerequisite_id" uuid NOT NULL,
  PRIMARY KEY ("plant_id", "task_id", "prerequisite_id"),
  CONSTRAINT "task_dependency_ck_0" CHECK (task_id <> prerequisite_id)
);

CREATE TABLE "recurrence" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "plant_id" uuid NOT NULL,
  "interval" text NOT NULL,
  "end_date" date,
  "timezone" text NOT NULL,
  "local_time" time,
  "source_task_id" uuid NOT NULL,
  "source_revision" bigint NOT NULL,
  "stopped_at" timestamptz,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "recurrence_uq_0" UNIQUE ("id", "plant_id"),
  CONSTRAINT "recurrence_ck_0" CHECK (revision >= 1),
  CONSTRAINT "recurrence_ck_1" CHECK ("interval" in ('daily', 'weekly', 'biweekly', 'monthly', 'quarterly', 'yearly'))
);

CREATE TABLE "obligation" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "plant_id" uuid NOT NULL,
  "meeting_id" uuid NOT NULL,
  "person_id" uuid,
  "kind" text NOT NULL,
  "origin_at" timestamptz NOT NULL,
  "origin_date" date NOT NULL,
  "timezone" text NOT NULL,
  "formula_version" text NOT NULL,
  "due_date" date NOT NULL,
  "assignee_id" uuid,
  "waived_at" timestamptz,
  "waiver_reason" text,
  "superseded_at" timestamptz,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "obligation_uq_0" UNIQUE ("id", "plant_id"),
  CONSTRAINT "obligation_ck_0" CHECK (revision >= 1),
  CONSTRAINT "obligation_ck_1" CHECK (kind in ('follow_up', 'evaluation')),
  CONSTRAINT "obligation_ck_2" CHECK ((kind = 'follow_up') = (person_id is not null))
);

CREATE UNIQUE INDEX "obligation_uq_1" ON "obligation" ("meeting_id", "person_id", "kind") WHERE person_id is not null;

CREATE UNIQUE INDEX "obligation_uq_2" ON "obligation" ("meeting_id", "kind") WHERE person_id is null;

CREATE TABLE "contact_outcome" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "plant_id" uuid NOT NULL,
  "person_id" uuid NOT NULL,
  "task_id" uuid,
  "obligation_id" uuid,
  "meeting_id" uuid,
  "outcome" text NOT NULL,
  "occurred_at" timestamptz NOT NULL,
  "recorded_at" timestamptz NOT NULL,
  "contact_channel" text,
  "notes" text,
  "supersedes_id" uuid,
  "voided_at" timestamptz,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "contact_outcome_uq_0" UNIQUE ("id", "plant_id"),
  CONSTRAINT "contact_outcome_ck_0" CHECK (revision >= 1),
  CONSTRAINT "contact_outcome_ck_1" CHECK (outcome in ('contacted', 'attempted_no_contact', 'administrative_completion', 'no_longer_needed')),
  CONSTRAINT "contact_outcome_ck_2" CHECK (occurred_at <= recorded_at),
  CONSTRAINT "contact_outcome_ck_3" CHECK (contact_channel in ('email', 'in_person', 'other', 'phone', 'text', 'video'))
);

CREATE TABLE "phase_transition" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "plant_id" uuid NOT NULL,
  "kind" text NOT NULL,
  "from_phase" integer,
  "to_phase" integer NOT NULL,
  "reason" text NOT NULL,
  "occurred_at" timestamptz NOT NULL,
  "recorded_at" timestamptz NOT NULL,
  "operation_id" uuid NOT NULL,
  "criterion_version_id" uuid,
  "offer_answer" text,
  "answered_at" timestamptz,
  PRIMARY KEY ("id"),
  CONSTRAINT "phase_transition_uq_0" UNIQUE ("id", "plant_id"),
  CONSTRAINT "phase_transition_uq_1" UNIQUE ("operation_id"),
  CONSTRAINT "phase_transition_ck_0" CHECK (kind in ('creation', 'initial_declaration', 'movement', 'noop')),
  CONSTRAINT "phase_transition_ck_1" CHECK (offer_answer in ('accepted', 'declined')),
  CONSTRAINT "phase_transition_ck_2" CHECK (to_phase between 0 and 6),
  CONSTRAINT "phase_transition_ck_3" CHECK (from_phase is null or from_phase between 0 and 6),
  CONSTRAINT "phase_transition_ck_4" CHECK (kind <> 'creation' or (from_phase is null and to_phase = 1)),
  CONSTRAINT "phase_transition_ck_5" CHECK ((offer_answer is null) = (answered_at is null))
);

CREATE UNIQUE INDEX "phase_transition_uq_2" ON "phase_transition" ("plant_id") WHERE kind = 'creation';

CREATE UNIQUE INDEX "phase_transition_uq_3" ON "phase_transition" ("plant_id") WHERE kind = 'initial_declaration';

CREATE TABLE "attestation" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "plant_id" uuid NOT NULL,
  "key" text NOT NULL,
  "reference_version_id" uuid NOT NULL,
  "person_id" uuid,
  "state" text NOT NULL,
  "answer" boolean,
  "as_of" date NOT NULL,
  "attested_at" timestamptz NOT NULL,
  "period_start" date,
  "period_end" date,
  "attendance_continuous" boolean,
  "volunteering_continuous" boolean,
  "statement" text,
  "source_description" text,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "attestation_uq_0" UNIQUE ("id", "plant_id"),
  CONSTRAINT "attestation_ck_0" CHECK (revision >= 1),
  CONSTRAINT "attestation_ck_1" CHECK (key in ('values_documented', 'financial_base_established', 'core_group_giving', 'prayer_leader_assigned', 'prayer_rhythm_established', 'prayer_in_gatherings', 'systems_tested', 'worship_agreement', 'community', 'promotion_plan', 'relationship', 'leadership_candidate')),
  CONSTRAINT "attestation_ck_2" CHECK (state in ('answered', 'unanswered', 'retracted')),
  CONSTRAINT "attestation_ck_3" CHECK (key <> 'leadership_candidate' or (person_id is not null and period_start is not null and period_end is not null and attendance_continuous is not null and volunteering_continuous is not null)),
  CONSTRAINT "attestation_ck_4" CHECK (period_end is null or period_start <= period_end),
  CONSTRAINT "attestation_ck_5" CHECK (key not in ('values_documented','financial_base_established','core_group_giving','prayer_leader_assigned','prayer_rhythm_established','prayer_in_gatherings','systems_tested') or ((state = 'answered' and answer is not null) or (state in ('unanswered','retracted') and answer is null)))
);

CREATE UNIQUE INDEX "attestation_uq_1" ON "attestation" ("plant_id", "key") WHERE person_id is null;

CREATE UNIQUE INDEX "attestation_uq_2" ON "attestation" ("plant_id", "key", "person_id") WHERE person_id is not null;

CREATE TABLE "launch" (
  "plant_id" uuid NOT NULL,
  "target_date" date,
  "actual_date" date,
  "status" text NOT NULL,
  "attendance" integer,
  "decisions" integer,
  "outcome_notes" text,
  "outcome_recorded_at" timestamptz,
  "reference_version_id" uuid,
  "summary_document_id" uuid,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("plant_id"),
  CONSTRAINT "launch_ck_0" CHECK (revision >= 1),
  CONSTRAINT "launch_ck_1" CHECK (status in ('planning', 'scheduled', 'postponed', 'completed')),
  CONSTRAINT "launch_ck_2" CHECK (attendance is null or attendance between 0 and 1000000),
  CONSTRAINT "launch_ck_3" CHECK (decisions is null or decisions between 0 and 1000000),
  CONSTRAINT "launch_ck_4" CHECK (status <> 'postponed' or target_date is null)
);

CREATE TABLE "launch_milestone" (
