  "notes" text,
  "voided_at" timestamptz,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "launch_guest_uq_0" UNIQUE ("id", "plant_id"),
  CONSTRAINT "launch_guest_ck_0" CHECK (revision >= 1),
  CONSTRAINT "launch_guest_ck_1" CHECK (kind in ('first_time', 'returning', 'core_group', 'launch_team', 'other'))
);

CREATE UNIQUE INDEX "launch_guest_uq_1" ON "launch_guest" ("plant_id", "person_id") WHERE voided_at is null;

CREATE TABLE "launch_debrief" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "plant_id" uuid NOT NULL,
  "form_version_id" uuid NOT NULL,
  "version_number" integer NOT NULL,
  "submitted_at" timestamptz,
  "what_went_well" text,
  "what_to_change" text,
  "welcoming" text,
  "children" text,
  "worship" text,
  "logistics" text,
  "guest_follow_up" text,
  "operational_support" text,
  "missing_names" text,
  "missing_count" integer,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
