  CONSTRAINT "launch_debrief_uq_1" UNIQUE ("plant_id", "version_number"),
  CONSTRAINT "launch_debrief_ck_0" CHECK (revision >= 1),
  CONSTRAINT "launch_debrief_ck_1" CHECK (missing_names in ('no', 'yes')),
  CONSTRAINT "launch_debrief_ck_2" CHECK ((missing_names = 'yes' and missing_count > 0) or (missing_names is distinct from 'yes' and missing_count is null))
);

CREATE UNIQUE INDEX "launch_debrief_uq_2" ON "launch_debrief" ("plant_id") WHERE submitted_at is null;

CREATE TABLE "private_calendar" (
  "account_id" uuid NOT NULL,
