  CONSTRAINT "private_week_ck_2" CHECK (num_nonnulls(spiritually,marriage_family,financially,pace) in (0,4)),
  CONSTRAINT "private_week_ck_3" CHECK (note is null or length(note) <= 2000),
  CONSTRAINT "private_week_ck_4" CHECK (spiritually in ('steady', 'strained', 'struggling')),
  CONSTRAINT "private_week_ck_5" CHECK (marriage_family in ('steady', 'strained', 'struggling')),
  CONSTRAINT "private_week_ck_6" CHECK (financially in ('steady', 'strained', 'struggling')),
  CONSTRAINT "private_week_ck_7" CHECK (pace in ('steady', 'strained', 'struggling'))
);

CREATE TABLE "private_week_revision" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
