  CONSTRAINT "private_week_revision_ck_1" CHECK (marriage_family in ('steady', 'strained', 'struggling')),
  CONSTRAINT "private_week_revision_ck_2" CHECK (financially in ('steady', 'strained', 'struggling')),
  CONSTRAINT "private_week_revision_ck_3" CHECK (pace in ('steady', 'strained', 'struggling'))
);

CREATE TABLE "reference_release" (
