  CONSTRAINT "article_revision_ck_0" CHECK (content_type in ('safe_mdx', 'safe_nodes')),
  CONSTRAINT "article_revision_ck_1" CHECK (phase is null or phase between 0 and 6),
  CONSTRAINT "article_revision_ck_2" CHECK (tenant_id = '00000000-0000-0000-0000-000000000000'::uuid or content_type = 'safe_nodes'),
  CONSTRAINT "article_revision_ck_3" CHECK ((tenant_id = '00000000-0000-0000-0000-000000000000'::uuid) = (release_id is not null))
);

