  CONSTRAINT "article_link_ck_1" CHECK ((kind = 'guide') = (route_pattern is not null))
);

CREATE UNIQUE INDEX "article_link_uq_0" ON "article_link" ("revision_id", "target_article_id") WHERE kind = 'related';

CREATE UNIQUE INDEX "article_link_uq_1" ON "article_link" ("revision_id", "route_pattern") WHERE kind = 'guide';

