  CONSTRAINT "wiki_preference_ck_0" CHECK (revision >= 1),
  CONSTRAINT "wiki_preference_ck_1" CHECK (group_kind in ('sending_church', 'sending_network')),
  CONSTRAINT "wiki_preference_ck_2" CHECK (position >= 0)
);

CREATE TABLE "reading" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "account_id" uuid NOT NULL,
  "article_id" uuid NOT NULL,
  "last_revision_id" uuid,
  "plant_context_id" uuid,
  "observed_fraction" numeric NOT NULL,
  "resume_position" text,
  "last_viewed_at" timestamptz,
  "completed_at" timestamptz,
  "completed_revision_id" uuid,
  "completed_fraction" numeric,
  "policy_version" text NOT NULL,
  "last_read_meaningful_sequence" bigint NOT NULL,
