  CONSTRAINT "reading_uq_1" UNIQUE ("account_id", "article_id"),
  CONSTRAINT "reading_ck_0" CHECK (revision >= 1),
  CONSTRAINT "reading_ck_1" CHECK (observed_fraction between 0 and 1),
  CONSTRAINT "reading_ck_2" CHECK (completed_fraction is null or completed_fraction between 0 and 1),
  CONSTRAINT "reading_ck_3" CHECK ((completed_at is null) = (completed_revision_id is null))
);

CREATE TABLE "passage" (
