);

CREATE TABLE "file_object" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id" uuid NOT NULL,
  "purpose" text NOT NULL,
  "opaque_key" text NOT NULL,
  "media_type" text NOT NULL,
  "max_bytes" bigint NOT NULL,
  "byte_count" bigint,
  "sha256" text,
  "state" text NOT NULL,
  "upload_key" text NOT NULL,
  "expires_at" timestamptz,
  "claim_generation" bigint NOT NULL,
  "retention_until" timestamptz,
  "purge_requested_at" timestamptz,
  "purged_at" timestamptz,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "file_object_uq_0" UNIQUE ("opaque_key"),
  CONSTRAINT "file_object_uq_1" UNIQUE ("upload_key"),
  CONSTRAINT "file_object_uq_2" UNIQUE ("id", "tenant_id"),
  CONSTRAINT "file_object_ck_0" CHECK (revision >= 1),
  CONSTRAINT "file_object_ck_1" CHECK (purpose in ('avatar', 'person_photo', 'commitment', 'generated', 'native_import', 'assistant_staging', 'communication_attachment')),
  CONSTRAINT "file_object_ck_2" CHECK (state in ('pending', 'ready', 'failed', 'cleanup', 'purged')),
  CONSTRAINT "file_object_ck_3" CHECK (byte_count is null or byte_count between 1 and max_bytes),
  CONSTRAINT "file_object_ck_4" CHECK (state <> 'ready' or (byte_count is not null and sha256 is not null)),
  CONSTRAINT "file_object_ck_5" CHECK (tenant_id <> '00000000-0000-0000-0000-000000000000'::uuid)
);

CREATE TABLE "document" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
