  CONSTRAINT "document_ck_0" CHECK (revision >= 1),
  CONSTRAINT "document_ck_1" CHECK (kind in ('native', 'core_values', 'launch_summary')),
  CONSTRAINT "document_ck_2" CHECK (tenant_id <> '00000000-0000-0000-0000-000000000000'::uuid)
);

CREATE TABLE "document_revision" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id" uuid NOT NULL,
