  CONSTRAINT "document_revision_uq_1" UNIQUE ("id", "tenant_id"),
  CONSTRAINT "document_revision_ck_0" CHECK (import_format in ('text', 'docx')),
  CONSTRAINT "document_revision_ck_1" CHECK (import_state in ('ready', 'failed')),
  CONSTRAINT "document_revision_ck_2" CHECK (tenant_id <> '00000000-0000-0000-0000-000000000000'::uuid)
);

CREATE TABLE "generated_document" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id" uuid NOT NULL,
  "template_version_id" uuid NOT NULL,
  "saved_template_name" text NOT NULL,
  "renderer_version" text NOT NULL,
