  CONSTRAINT "generated_document_ck_1" CHECK (tenant_id <> '00000000-0000-0000-0000-000000000000'::uuid)
);

CREATE TABLE "assessment" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id" uuid NOT NULL,
  "demand_kind" text NOT NULL,
  "request_key" text NOT NULL,
  "request_digest" text NOT NULL,
  "refresh_window" date,
  "source_revision" bigint NOT NULL,
  "reference_activation_id" uuid NOT NULL,
  "rubric_version_id" uuid NOT NULL,
  "policy_version" text NOT NULL,
  "formula_version" text NOT NULL,
  "schema_version" text NOT NULL,
  "as_of" timestamptz NOT NULL,
  "captured_phase" integer,
  "timezone" text NOT NULL,
  "snapshot_hash" text,
  "model_id" text NOT NULL,
  "model_parameters" jsonb NOT NULL,
  "state" text NOT NULL,
  "job_id" uuid,
  "draft_count" integer NOT NULL,
  "reserved_input" integer NOT NULL,
  "reserved_output" integer NOT NULL,
  "used_input" integer NOT NULL,
  "used_output" integer NOT NULL,
  "deadline_at" timestamptz,
  "failure_code" text,
  "last_violation_code" text,
  "available_at" timestamptz,
  "human_seen_at" timestamptz,
  "released_at" timestamptz,
  "summary" text,
  "input_manifest_hash" text,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "assessment_uq_0" UNIQUE ("tenant_id", "request_key"),
  CONSTRAINT "assessment_uq_1" UNIQUE ("id", "tenant_id"),
  CONSTRAINT "assessment_ck_0" CHECK (revision >= 1),
  CONSTRAINT "assessment_ck_1" CHECK (demand_kind in ('material', 'daily', 'manual', 'operator')),
  CONSTRAINT "assessment_ck_2" CHECK (state in ('owed', 'captured', 'drafting', 'validated', 'complete', 'deferred', 'failed', 'superseded')),
  CONSTRAINT "assessment_ck_3" CHECK (draft_count between 0 and 3),
  CONSTRAINT "assessment_ck_4" CHECK (reserved_input between 0 and 60000),
  CONSTRAINT "assessment_ck_5" CHECK (reserved_output between 0 and 12000),
  CONSTRAINT "assessment_ck_6" CHECK (captured_phase is null or captured_phase between 0 and 6),
  CONSTRAINT "assessment_ck_7" CHECK (state <> 'complete' or (snapshot_hash is not null and available_at is not null and summary is not null)),
  CONSTRAINT "assessment_ck_8" CHECK (summary is null or length(summary) between 10 and 600),
  CONSTRAINT "assessment_ck_9" CHECK (tenant_id <> '00000000-0000-0000-0000-000000000000'::uuid)
);

CREATE TABLE "assessment_fact" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id" uuid NOT NULL,
  "assessment_id" uuid NOT NULL,
  "path" text NOT NULL,
  "value_state" text NOT NULL,
  "provenance" text NOT NULL,
  "number_value" numeric,
  "boolean_value" boolean,
  "text_value" text,
  "date_value" date,
  "unit" text,
  "occurred_at" timestamptz,
  "source_revision" bigint,
  "formula_version" text NOT NULL,
  "kind" text NOT NULL,
  "standing" text,
  "judgment" text,
  "evidence_quality" text,
  PRIMARY KEY ("id"),
  CONSTRAINT "assessment_fact_uq_0" UNIQUE ("assessment_id", "path"),
  CONSTRAINT "assessment_fact_uq_1" UNIQUE ("id", "tenant_id"),
  CONSTRAINT "assessment_fact_ck_0" CHECK (value_state in ('known', 'unknown', 'unanswered', 'retracted', 'partial', 'unavailable')),
  CONSTRAINT "assessment_fact_ck_1" CHECK (provenance in ('measured', 'calculated', 'human_attested')),
  CONSTRAINT "assessment_fact_ck_2" CHECK (value_state <> 'known' or kind <> 'fact' or num_nonnulls(number_value,boolean_value,text_value,date_value) = 1),
  CONSTRAINT "assessment_fact_ck_3" CHECK (num_nonnulls(number_value,boolean_value,text_value,date_value) <= 1),
  CONSTRAINT "assessment_fact_ck_4" CHECK (kind in ('fact', 'lens', 'criterion', 'regional')),
  CONSTRAINT "assessment_fact_ck_5" CHECK (standing in ('met', 'not_met', 'unknown', 'not_tracked', 'on_track', 'attention', 'watch', 'strength', 'limited_visibility', 'not_shared')),
  CONSTRAINT "assessment_fact_ck_6" CHECK (judgment in ('attention', 'watch', 'noted', 'strength', 'not_addressed')),
  CONSTRAINT "assessment_fact_ck_7" CHECK ((kind = 'fact' and standing is null) or (kind <> 'fact' and standing is not null)),
  CONSTRAINT "assessment_fact_ck_8" CHECK (kind = 'fact' or num_nonnulls(number_value,boolean_value,text_value,date_value) = 0),
  CONSTRAINT "assessment_fact_ck_9" CHECK (evidence_quality in ('attested', 'measured', 'unknown')),
  CONSTRAINT "assessment_fact_ck_10" CHECK (tenant_id <> '00000000-0000-0000-0000-000000000000'::uuid)
);

CREATE TABLE "finding" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id" uuid NOT NULL,
  "assessment_id" uuid NOT NULL,
  "concern_key" text NOT NULL,
  "audience" text NOT NULL,
  "category" text NOT NULL,
  "urgency" text NOT NULL,
  "title" text NOT NULL,
  "body" text NOT NULL,
  "rank" integer NOT NULL,
  "focus" text,
  PRIMARY KEY ("id"),
  CONSTRAINT "finding_uq_0" UNIQUE ("assessment_id", "audience", "concern_key"),
  CONSTRAINT "finding_uq_1" UNIQUE ("id", "tenant_id"),
  CONSTRAINT "finding_ck_0" CHECK (audience in ('planter', 'oversight')),
  CONSTRAINT "finding_ck_1" CHECK (category in ('people', 'meetings', 'tasks', 'ministry', 'wiki', 'shared_findings')),
  CONSTRAINT "finding_ck_2" CHECK (urgency in ('positive', 'info', 'watch', 'urgent')),
  CONSTRAINT "finding_ck_3" CHECK (focus in ('primary', 'supplement', 'positive')),
  CONSTRAINT "finding_ck_4" CHECK (length(title) between 3 and 140),
  CONSTRAINT "finding_ck_5" CHECK (length(body) between 10 and 1200),
  CONSTRAINT "finding_ck_6" CHECK (tenant_id <> '00000000-0000-0000-0000-000000000000'::uuid)
);

CREATE TABLE "assessment_contributor" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
