  CONSTRAINT "assessment_contributor_uq_0" UNIQUE ("id", "organization_id"),
  CONSTRAINT "assessment_contributor_uq_1" UNIQUE ("assessment_id", "plant_id")
);

CREATE TABLE "reader_feedback" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "plant_context_id" uuid,
  "organization_context_id" uuid,
  "account_id" uuid NOT NULL,
  "assessment_id" uuid,
  "finding_id" uuid,
  "rating" text NOT NULL,
  "comment" text,
  "reference_version_id" uuid,
  "revision" bigint NOT NULL DEFAULT 1,
  "article_id" uuid,
  "article_revision_id" uuid,
  "organization_source_id" uuid,
  PRIMARY KEY ("id"),
  CONSTRAINT "reader_feedback_ck_0" CHECK (revision >= 1),
  CONSTRAINT "reader_feedback_ck_1" CHECK (rating in ('useful', 'not_useful', 'helpful', 'unhelpful')),
  CONSTRAINT "reader_feedback_ck_2" CHECK (num_nonnulls(assessment_id,finding_id,article_revision_id) = 1),
  CONSTRAINT "reader_feedback_ck_3" CHECK ((article_revision_id is null and rating in ('useful','not_useful') and article_id is null) or (article_revision_id is not null and rating in ('helpful','unhelpful') and article_id is not null and plant_context_id is not null)),
  CONSTRAINT "reader_feedback_ck_4" CHECK (num_nonnulls(plant_context_id,organization_context_id) = 1)
);

CREATE UNIQUE INDEX "reader_feedback_uq_0" ON "reader_feedback" ("account_id", "assessment_id") WHERE assessment_id is not null;

CREATE UNIQUE INDEX "reader_feedback_uq_1" ON "reader_feedback" ("account_id", "finding_id") WHERE finding_id is not null;

CREATE UNIQUE INDEX "reader_feedback_uq_2" ON "reader_feedback" ("account_id", "plant_context_id", "article_id") WHERE article_revision_id is not null and organization_source_id is null;

CREATE UNIQUE INDEX "reader_feedback_uq_3" ON "reader_feedback" ("account_id", "plant_context_id", "article_id", "organization_source_id") WHERE article_revision_id is not null and organization_source_id is not null;

CREATE TABLE "plant_geography" (
