  "review_digest" text,
  "original_communication_id" uuid,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "communication_uq_0" UNIQUE ("id", "plant_id"),
  CONSTRAINT "communication_ck_0" CHECK (revision >= 1),
  CONSTRAINT "communication_ck_1" CHECK (state in ('draft', 'reviewed', 'dispatching', 'sent', 'scheduled', 'cancelling', 'cancelled', 'partial', 'unknown', 'failed'))
);

CREATE TABLE "communication_recipient" (
