CREATE TABLE "mail" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id" uuid NOT NULL,
  "recipient_account_id" uuid,
  "recipient_person_id" uuid,
  "recipient_address_encrypted" text,
  "purpose" text NOT NULL,
  "logical_key" text NOT NULL,
  "operation_id" uuid,
  "notice_id" uuid,
  "payload_hash" text NOT NULL,
  "audience_hash" text NOT NULL,
  "frozen_payload" jsonb,
  "scheduled_at" timestamptz,
  "state" text NOT NULL,
  "provider_message_id" text,
  "accepted_at" timestamptz,
  "sent_at" timestamptz,
  "delivered_at" timestamptz,
  "bounced_at" timestamptz,
  "complained_at" timestamptz,
  "opened_at" timestamptz,
  "clicked_at" timestamptz,
  "cancel_requested_at" timestamptz,
  "cancel_confirmed_at" timestamptz,
  "job_id" uuid,
  "original_mail_id" uuid,
  "revision" bigint NOT NULL DEFAULT 1,
  "created_at" timestamptz NOT NULL,
  "address_hash" text,
  PRIMARY KEY ("id"),
  CONSTRAINT "mail_uq_0" UNIQUE ("tenant_id", "logical_key"),
  CONSTRAINT "mail_uq_1" UNIQUE ("id", "tenant_id"),
  CONSTRAINT "mail_ck_0" CHECK (revision >= 1),
  CONSTRAINT "mail_ck_1" CHECK (num_nonnulls(recipient_account_id,recipient_person_id) <= 1),
  CONSTRAINT "mail_ck_2" CHECK (state in ('pending', 'dispatched', 'unknown', 'refused', 'accepted', 'scheduled', 'sent', 'cancelled', 'failed')),
  CONSTRAINT "mail_ck_3" CHECK ((frozen_payload is null) = (recipient_address_encrypted is null)),
  CONSTRAINT "mail_ck_4" CHECK (frozen_payload is not null or state in ('unknown','refused','accepted','scheduled','sent','cancelled','failed')),
  CONSTRAINT "mail_ck_5" CHECK ((frozen_payload is null) = (address_hash is null)),
  CONSTRAINT "mail_ck_6" CHECK (purpose in ('communication', 'discovery_receipt', 'email_change', 'email_verification', 'notification', 'oversight_digest', 'password_reset', 'planter_digest', 'relationship_invitation', 'relationship_receipt', 'seat_invitation')),
  CONSTRAINT "mail_ck_7" CHECK (tenant_id <> '00000000-0000-0000-0000-000000000000'::uuid or frozen_payload is null)
);

