  CONSTRAINT "mail_attempt_uq_1" UNIQUE ("id", "request_id"),
  CONSTRAINT "mail_attempt_uq_2" UNIQUE ("id", "tenant_id"),
  CONSTRAINT "mail_attempt_uq_3" UNIQUE ("id", "request_id", "tenant_id"),
  CONSTRAINT "mail_attempt_ck_0" CHECK (outcome in ('in_flight', 'accepted', 'refused', 'partial', 'unknown'))
);

CREATE TABLE "provider_event" (
