  "unsubscribe_revision" bigint NOT NULL,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "notification_preference_uq_0" UNIQUE ("id", "account_id"),
  CONSTRAINT "notification_preference_uq_1" UNIQUE ("account_id", "category", "channel"),
  CONSTRAINT "notification_preference_ck_0" CHECK (revision >= 1),
  CONSTRAINT "notification_preference_ck_1" CHECK (category in ('task', 'meeting', 'phase', 'insight', 'planter_digest', 'oversight_digest', 'relationship', 'reference_update')),
  CONSTRAINT "notification_preference_ck_2" CHECK (channel in ('email', 'in_app')),
  CONSTRAINT "notification_preference_ck_3" CHECK (cadence in ('daily', 'weekly')),
  CONSTRAINT "notification_preference_ck_4" CHECK (weekday is null or weekday between 0 and 6),
  CONSTRAINT "notification_preference_ck_5" CHECK (hour is null or hour between 0 and 23),
  CONSTRAINT "notification_preference_ck_6" CHECK (category <> 'reference_update' or channel = 'in_app')
);

CREATE TABLE "notice" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
