  "eligible_at" timestamptz NOT NULL,
  "created_at" timestamptz NOT NULL,
  "schedule_date" date,
  "schedule_time" time,
  "timezone" text,
  "resolver_version" text,
  "read_at" timestamptz,
  "archived_at" timestamptz,
  "cancelled_at" timestamptz,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "notice_uq_0" UNIQUE ("recipient_id", "logical_key"),
  CONSTRAINT "notice_uq_1" UNIQUE ("id", "tenant_id"),
  CONSTRAINT "notice_ck_0" CHECK (revision >= 1),
  CONSTRAINT "notice_ck_1" CHECK (category in ('task', 'meeting', 'phase', 'insight', 'relationship', 'reference_update', 'digest', 'launch')),
  CONSTRAINT "notice_ck_2" CHECK (purpose in ('insight_available', 'launch_milestone', 'meeting_evaluation', 'meeting_invitation', 'meeting_reminder', 'oversight_digest', 'phase_offer', 'phase_transition', 'planter_digest', 'reference_update', 'relationship_decision', 'relationship_invitation', 'task_assignment', 'task_due')),
  CONSTRAINT "notice_ck_3" CHECK (tenant_id <> '00000000-0000-0000-0000-000000000000'::uuid)
);

CREATE TABLE "digest_coverage" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id" uuid NOT NULL,
  "recipient_id" uuid NOT NULL,
  "purpose" text NOT NULL,
  "cadence" text NOT NULL,
  "timezone" text NOT NULL,
  "covered_through" date,
  "last_mail_id" uuid,
  "last_operation_id" uuid,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "digest_coverage_uq_0" UNIQUE ("tenant_id", "recipient_id", "purpose"),
  CONSTRAINT "digest_coverage_uq_1" UNIQUE ("id", "tenant_id"),
  CONSTRAINT "digest_coverage_ck_0" CHECK (revision >= 1),
  CONSTRAINT "digest_coverage_ck_1" CHECK (purpose in ('planter', 'oversight')),
  CONSTRAINT "digest_coverage_ck_2" CHECK (cadence in ('daily', 'weekly')),
  CONSTRAINT "digest_coverage_ck_3" CHECK (tenant_id <> '00000000-0000-0000-0000-000000000000'::uuid)
);

CREATE TABLE "conversation" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id" uuid NOT NULL,
  "owner_id" uuid NOT NULL,
  "title" text NOT NULL,
  "state" text NOT NULL,
  "revision" bigint NOT NULL DEFAULT 1,
  "plan_document" jsonb,
  "plan_revision" bigint,
  PRIMARY KEY ("id"),
  CONSTRAINT "conversation_uq_0" UNIQUE ("id", "tenant_id"),
  CONSTRAINT "conversation_ck_0" CHECK (revision >= 1),
  CONSTRAINT "conversation_ck_1" CHECK (state in ('open', 'archived')),
  CONSTRAINT "conversation_ck_2" CHECK ((plan_document is null) = (plan_revision is null)),
  CONSTRAINT "conversation_ck_3" CHECK (plan_revision is null or plan_revision >= 1),
  CONSTRAINT "conversation_ck_4" CHECK (tenant_id <> '00000000-0000-0000-0000-000000000000'::uuid)
);

CREATE TABLE "conversation_entry" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id" uuid NOT NULL,
  "conversation_id" uuid NOT NULL,
  "sequence" bigint NOT NULL,
  "request_key" text,
  "kind" text NOT NULL,
  "role" text,
  "body" text,
  "display_payload" jsonb,
  "occurred_at" timestamptz NOT NULL,
  "recorded_at" timestamptz NOT NULL,
  "object_id" uuid,
  "expires_at" timestamptz,
  "review_id" uuid,
  "operation_id" uuid,
  "state" text,
  "bound_effect_id" uuid,
  PRIMARY KEY ("id"),
  CONSTRAINT "conversation_entry_uq_0" UNIQUE ("conversation_id", "sequence"),
  CONSTRAINT "conversation_entry_uq_2" UNIQUE ("id", "tenant_id"),
  CONSTRAINT "conversation_entry_ck_0" CHECK (kind in ('message', 'read', 'clarification', 'review', 'progress', 'receipt', 'boundary', 'summary', 'attachment')),
  CONSTRAINT "conversation_entry_ck_1" CHECK (role in ('user', 'assistant')),
  CONSTRAINT "conversation_entry_ck_2" CHECK ((kind = 'message') = (role is not null)),
  CONSTRAINT "conversation_entry_ck_3" CHECK (state in ('bound', 'claimed', 'failed', 'staged')),
  CONSTRAINT "conversation_entry_ck_4" CHECK ((kind = 'attachment' and object_id is not null and operation_id is not null and state is not null and expires_at is null) or (kind <> 'attachment' and state is null and bound_effect_id is null)),
  CONSTRAINT "conversation_entry_ck_5" CHECK (state <> 'bound' or bound_effect_id is not null),
  CONSTRAINT "conversation_entry_ck_6" CHECK (tenant_id <> '00000000-0000-0000-0000-000000000000'::uuid)
);

CREATE UNIQUE INDEX "conversation_entry_uq_1" ON "conversation_entry" ("conversation_id", "request_key") WHERE request_key is not null;

CREATE TABLE "review" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id" uuid NOT NULL,
  "conversation_id" uuid NOT NULL,
  "proposal_number" integer NOT NULL,
  "digest" text NOT NULL,
  "effect_manifest_hash" text NOT NULL,
  "published_at" timestamptz NOT NULL,
  "candidate_notes" text,
  "approved_by_id" uuid,
  "approved_at" timestamptz,
  "witness_hash" text,
  "cancelled_at" timestamptz,
  "superseded_at" timestamptz,
  PRIMARY KEY ("id"),
  CONSTRAINT "review_uq_0" UNIQUE ("conversation_id", "proposal_number"),
  CONSTRAINT "review_uq_1" UNIQUE ("id", "tenant_id"),
  CONSTRAINT "review_ck_0" CHECK (num_nonnulls(approved_by_id,approved_at,witness_hash) in (0,3)),
  CONSTRAINT "review_ck_1" CHECK (tenant_id <> '00000000-0000-0000-0000-000000000000'::uuid)
);

CREATE TABLE "operation" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id" uuid NOT NULL,
  "actor_id" uuid,
  "actor_tombstone" text,
  "name" text NOT NULL,
  "request_key" text NOT NULL,
  "request_digest" text NOT NULL,
  "review_id" uuid,
  "conversation_id" uuid,
  "state" text NOT NULL,
  "outcome" text,
  "started_at" timestamptz NOT NULL,
  "completed_at" timestamptz,
  "safe_error" text,
  "job_id" uuid,
  "tool_calls" integer NOT NULL,
  "reserved_input" integer NOT NULL,
  "reserved_output" integer NOT NULL,
  "used_input" integer NOT NULL,
  "used_output" integer NOT NULL,
  "deadline_at" timestamptz,
  "stop_reason" text,
  "model_id" text,
  "cache_tokens" integer,
  "cost_basis" numeric,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "operation_uq_0" UNIQUE ("tenant_id", "request_key"),
  CONSTRAINT "operation_uq_2" UNIQUE ("id", "tenant_id"),
  CONSTRAINT "operation_ck_0" CHECK (revision >= 1),
  CONSTRAINT "operation_ck_1" CHECK (state in ('pending', 'running', 'complete', 'partial', 'failed', 'cancelled', 'reconcile')),
  CONSTRAINT "operation_ck_2" CHECK (outcome in ('committed', 'no_effect', 'partial', 'conflict', 'refused')),
  CONSTRAINT "operation_ck_3" CHECK (tool_calls between 0 and 24),
  CONSTRAINT "operation_ck_4" CHECK (reserved_input between 0 and 128000),
  CONSTRAINT "operation_ck_5" CHECK (reserved_output between 0 and 16000),
