CREATE UNIQUE INDEX "effect_uq_0" ON "effect" ("operation_id", "effect_key") WHERE operation_id is not null;

CREATE UNIQUE INDEX "effect_uq_1" ON "effect" ("review_id", "effect_key") WHERE review_id is not null;

CREATE TABLE "effect_dependency" (
  "effect_id" uuid NOT NULL,
  "tenant_id" uuid NOT NULL,
  "prerequisite_id" uuid NOT NULL,
  "output_key" text,
  PRIMARY KEY ("effect_id", "prerequisite_id"),
  CONSTRAINT "effect_dependency_ck_0" CHECK (effect_id <> prerequisite_id)
);

CREATE TABLE "event" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id" uuid NOT NULL,
  "target_record_id" uuid NOT NULL,
  "operation_id" uuid,
  "effect_id" uuid,
  "actor_id" uuid,
  "actor_tombstone" text,
  "system_cause" text,
  "kind" text NOT NULL,
  "occurred_at" timestamptz NOT NULL,
  "recorded_at" timestamptz NOT NULL,
  "before_revision" bigint,
  "after_revision" bigint,
  "from_value" text,
  "to_value" text,
  "number_value" numeric,
  "occurrence_date" date,
  "reason" text,
  "diff" jsonb,
  "mail_attempt_id" uuid,
  "mail_request_id" uuid,
  "mail_position" integer,
  "usage_input" integer,
  "usage_output" integer,
  "cache_tokens" integer,
  "latency_ms" integer,
  "retry_after_seconds" integer,
  "event_key" text NOT NULL,
  "action" text,
  PRIMARY KEY ("id"),
  CONSTRAINT "event_uq_0" UNIQUE ("target_record_id", "event_key"),
  CONSTRAINT "event_uq_1" UNIQUE ("id", "tenant_id"),
  CONSTRAINT "event_ck_0" CHECK (num_nonnulls(mail_attempt_id,mail_request_id,mail_position) in (0,3)),
  CONSTRAINT "event_ck_1" CHECK (kind in ('create', 'edit', 'correct', 'retire', 'restore', 'merge', 'unmerge', 'stage_change', 'classification_change', 'commitment_change', 'assign', 'remove', 'accept', 'revoke', 'resend', 'role_change', 'leader_change', 'tick', 'untick', 'archive', 'earn', 'revoke_credit', 'offer_answer', 'publish', 'hide', 'read', 'progress', 'complete', 'reopen', 'waive', 'supersede', 'finalize', 'reconcile', 'noop', 'triage', 'suppress', 'suppression_clear', 'preference', 'model_attempt', 'tool_attempt', 'effect_result', 'mail_member', 'outcome', 'declaration', 'movement')),
  CONSTRAINT "event_ck_2" CHECK (num_nonnulls(actor_id,actor_tombstone,system_cause) = 1),
  CONSTRAINT "event_ck_3" CHECK (action in ('identity.credential_observed', 'identity.domain_accepted', 'identity.credential_changed', 'identity.credential_reconciled', 'identity.email_changed', 'identity.sessions_revoked', 'membership.created', 'membership.role_changed', 'membership.ended', 'invitation.claimed', 'invitation.revoked', 'plant.created', 'plant.profile_changed', 'organization.profile_changed', 'affiliation.approved', 'affiliation.ended', 'sharing.changed', 'people.created', 'people.updated', 'people.retired', 'people.restored', 'people.stage_changed', 'people.merged', 'people.unmerged', 'people.recorded', 'people.corrected', 'teams.changed', 'roles.changed', 'training.assigned', 'training.assignment_removed', 'training.completed', 'training.revoked', 'training.corrected', 'meetings.changed', 'meetings.finalized', 'meetings.corrected', 'meetings.rsvp_recorded', 'meetings.response_recorded', 'tasks.changed', 'tasks.completed', 'tasks.waived', 'followup.recorded', 'followup.corrected', 'phase.created', 'phase.declared', 'phase.transitioned', 'attestation.recorded', 'attestation.corrected', 'launch.changed', 'launch.outcome_recorded', 'launch.debrief_submitted', 'launch.summary_published', 'launch.corrected', 'wiki.published', 'wiki.hidden', 'wiki.source_order_changed', 'reference.activated', 'documents.saved', 'documents.copied', 'files.finalized', 'intelligence.requested', 'intelligence.published', 'intelligence.superseded', 'intelligence.feedback_recorded', 'communication.approved', 'communication.send_intended', 'mail.accepted', 'mail.delivered', 'mail.refused', 'mail.reconciled', 'mail.cancelled', 'feedback.received', 'feedback.publication_intended', 'feedback.published', 'feedback.reconciled', 'execution.started', 'execution.completed', 'execution.partial', 'execution.cancelled', 'execution.reconciled', 'account.deletion_requested', 'plant.deletion_requested', 'deletion.cancelled', 'deletion.live_purge_completed', 'recovery.copy_expired', 'recovery.restored', 'security.access_denied', 'security.bulk_export', 'security.audit_inspected', 'security.audit_exported', 'security.operator_accessed')),
  CONSTRAINT "event_ck_4" CHECK (action is null or diff is null or (jsonb_typeof(diff) = 'object' and octet_length(convert_to(diff::text, 'UTF8')) <= 2048))
);

CREATE TABLE "job" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id" uuid NOT NULL,
  "kind" text NOT NULL,
  "subject_record_id" uuid,
  "producer_key" text NOT NULL,
  "source_revision" bigint,
  "state" text NOT NULL,
  "eligible_at" timestamptz NOT NULL,
  "attempt_count" integer NOT NULL,
  "max_attempts" integer NOT NULL,
  "lease_owner" text,
  "lease_until" timestamptz,
  "claim_generation" bigint NOT NULL,
  "checkpoint_key" text,
  "next_attempt_at" timestamptz,
  "error_code" text,
  "finished_at" timestamptz,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "job_uq_0" UNIQUE ("kind", "subject_record_id", "producer_key"),
  CONSTRAINT "job_uq_2" UNIQUE ("id", "tenant_id"),
  CONSTRAINT "job_ck_0" CHECK (revision >= 1),
  CONSTRAINT "job_ck_1" CHECK (kind in ('mail', 'notification', 'digest', 'assessment', 'reference_generation', 'feedback_publication', 'object_cleanup', 'lifecycle_purge', 'assistant_turn', 'document_render')),
  CONSTRAINT "job_ck_2" CHECK (state in ('ready', 'claimed', 'retry_wait', 'reconcile', 'succeeded', 'failed', 'cancelled', 'superseded')),
  CONSTRAINT "job_ck_3" CHECK (attempt_count >= 0 and max_attempts >= 1),
  CONSTRAINT "job_ck_4" CHECK (claim_generation >= 0),
  CONSTRAINT "job_ck_5" CHECK ((lease_owner is null) = (lease_until is null)),
  CONSTRAINT "job_ck_6" CHECK (subject_record_id is not null or producer_key = 'sweep'),
  CONSTRAINT "job_ck_7" CHECK (tenant_id <> '00000000-0000-0000-0000-000000000000'::uuid or kind in ('mail', 'reference_generation', 'feedback_publication', 'object_cleanup', 'lifecycle_purge'))
);

CREATE UNIQUE INDEX "job_uq_1" ON "job" ("tenant_id", "kind") WHERE producer_key = 'sweep';

CREATE TABLE "feedback" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "account_id" uuid NOT NULL,
  "plant_context_id" uuid,
  "category" text NOT NULL,
  "description" text NOT NULL,
  "route_label" text,
  "submitted_at" timestamptz NOT NULL,
  "request_key" text NOT NULL,
  "triage_state" text NOT NULL,
  "revision_number" bigint NOT NULL,
  "page_label" text,
  "page_address" text,
  "church_label" text,
  "role_label" text,
  "browser" text,
  "screen_width" integer,
  "screen_height" integer,
  "theme" text,
  "app_version" text,
  PRIMARY KEY ("id"),
  CONSTRAINT "feedback_uq_0" UNIQUE ("id", "account_id"),
  CONSTRAINT "feedback_uq_1" UNIQUE ("account_id", "request_key"),
  CONSTRAINT "feedback_ck_0" CHECK (category in ('bug', 'suggestion', 'question', 'other')),
  CONSTRAINT "feedback_ck_1" CHECK (triage_state in ('new', 'reviewed', 'resolved', 'dismissed')),
  CONSTRAINT "feedback_ck_2" CHECK (length(btrim(description)) between 1 and 5000),
  CONSTRAINT "feedback_ck_3" CHECK (route_label is null or length(route_label) <= 500),
  CONSTRAINT "feedback_ck_4" CHECK (page_label is null or length(page_label) <= 500),
  CONSTRAINT "feedback_ck_5" CHECK (page_address is null or length(page_address) <= 500),
  CONSTRAINT "feedback_ck_6" CHECK (church_label is null or length(church_label) <= 200),
  CONSTRAINT "feedback_ck_7" CHECK (role_label is null or length(role_label) <= 200),
  CONSTRAINT "feedback_ck_8" CHECK (browser is null or length(browser) <= 500),
  CONSTRAINT "feedback_ck_9" CHECK (app_version is null or length(app_version) <= 100),
  CONSTRAINT "feedback_ck_10" CHECK (page_address is null or (page_address like '/%' and position('?' in page_address) = 0 and position('#' in page_address) = 0)),
  CONSTRAINT "feedback_ck_11" CHECK (theme is null or theme in ('light', 'dark')),
  CONSTRAINT "feedback_ck_12" CHECK (screen_width is null or screen_width between 1 and 100000),
  CONSTRAINT "feedback_ck_13" CHECK (screen_height is null or screen_height between 1 and 100000)
);

CREATE TABLE "feedback_publication" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "account_id" uuid,
  "feedback_id" uuid,
  "marker" uuid NOT NULL,
  "category" text,
  "public_area" text,
  "sanitized_title" text,
  "sanitized_body" text,
  "payload_hash" text NOT NULL,
  "repository_numeric_id" bigint NOT NULL,
  "repository_node_id" text NOT NULL,
  "repository_owner" text NOT NULL,
  "repository_name" text NOT NULL,
  "state" text NOT NULL,
  "issue_number" integer,
  "issue_node_id" text,
  "issue_url" text,
  "published_at" timestamptz,
  "effect_id" uuid,
  "revision" bigint NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  CONSTRAINT "feedback_publication_uq_0" UNIQUE ("id", "account_id"),
  CONSTRAINT "feedback_publication_uq_1" UNIQUE ("marker"),
  CONSTRAINT "feedback_publication_uq_2" UNIQUE ("feedback_id"),
  CONSTRAINT "feedback_publication_ck_0" CHECK (revision >= 1),
  CONSTRAINT "feedback_publication_ck_1" CHECK (state in ('pending', 'held', 'publishing', 'published', 'rejected', 'unknown')),
  CONSTRAINT "feedback_publication_ck_2" CHECK ((account_id is not null and feedback_id is not null and category is not null and public_area is not null and sanitized_title is not null and sanitized_body is not null) or (account_id is null and feedback_id is null and category is null and public_area is null and sanitized_title is null and sanitized_body is null)),
  CONSTRAINT "feedback_publication_ck_3" CHECK (account_id is not null or state in ('published','unknown'))
);

CREATE TABLE "prompt_dismissal" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "account_id" uuid NOT NULL,
  "plant_id" uuid NOT NULL,
  "prompt_key" text NOT NULL,
  "context_version" text NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "prompt_dismissal_uq_0" UNIQUE ("id", "account_id"),
  CONSTRAINT "prompt_dismissal_uq_1" UNIQUE ("account_id", "plant_id", "prompt_key", "context_version")
);

CREATE TABLE "lifecycle_witness" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "kind" text NOT NULL,
  "opaque_subject_id" uuid NOT NULL,
  "account_id" uuid,
  "plant_id" uuid,
  "request_id" uuid,
  "requester_id" uuid,
  "request_revision" bigint NOT NULL,
  "state" text NOT NULL,
  "requested_at" timestamptz,
  "live_purged_at" timestamptz,
  "copy_expires_at" timestamptz,
  "witness_checkpoint" bigint NOT NULL,
  "byte_manifest_hash" text,
  "cancellation_manifest_hash" text,
  "cleanup_state" text NOT NULL,
  "seat_id" uuid,
  "affiliation_id" uuid,
  "requester_opaque_id" uuid,
  "counterparty_organization_id" uuid,
  "cancel_until" timestamptz,
  "cancelled_at" timestamptz,
  PRIMARY KEY ("id"),
  CONSTRAINT "lifecycle_witness_uq_0" UNIQUE ("kind", "opaque_subject_id"),
  CONSTRAINT "lifecycle_witness_ck_0" CHECK (cleanup_state in ('not_started', 'in_progress', 'inaccessible', 'confirmed')),
  CONSTRAINT "lifecycle_witness_ck_1" CHECK (plant_id is null or kind = 'plant'),
  CONSTRAINT "lifecycle_witness_ck_2" CHECK (copy_expires_at is null or copy_expires_at <= live_purged_at + interval '168 hours'),
  CONSTRAINT "lifecycle_witness_ck_3" CHECK (kind in ('account', 'plant', 'seat', 'affiliation')),
  CONSTRAINT "lifecycle_witness_ck_4" CHECK (state in ('active', 'pending_deletion', 'purging', 'purged', 'cancelled', 'revoked')),
  CONSTRAINT "lifecycle_witness_ck_5" CHECK (num_nonnulls(account_id,plant_id,seat_id,affiliation_id) <= 1),
  CONSTRAINT "lifecycle_witness_ck_6" CHECK (account_id is null or kind in ('account')),
  CONSTRAINT "lifecycle_witness_ck_7" CHECK (seat_id is null or kind = 'seat'),
  CONSTRAINT "lifecycle_witness_ck_8" CHECK (affiliation_id is null or kind = 'affiliation'),
  CONSTRAINT "lifecycle_witness_ck_9" CHECK (kind not in ('account', 'plant') or state in ('active', 'pending_deletion', 'purging', 'purged', 'cancelled')),
  CONSTRAINT "lifecycle_witness_ck_10" CHECK (kind in ('account', 'plant') or state in ('active', 'revoked')),
  CONSTRAINT "lifecycle_witness_ck_11" CHECK (state not in ('pending_deletion', 'purging', 'purged', 'cancelled') or (request_id is not null and requested_at is not null and cancel_until is not null and request_revision >= 1)),
  CONSTRAINT "lifecycle_witness_ck_12" CHECK (cancel_until is null or (requested_at is not null and cancel_until = requested_at + interval '720 hours')),
  CONSTRAINT "lifecycle_witness_ck_13" CHECK ((state = 'cancelled') = (cancelled_at is not null)),
  CONSTRAINT "lifecycle_witness_ck_14" CHECK (cancelled_at is null or (cancelled_at >= requested_at and cancelled_at < cancel_until)),
  CONSTRAINT "lifecycle_witness_ck_15" CHECK ((state = 'purged') = (live_purged_at is not null)),
  CONSTRAINT "lifecycle_witness_ck_16" CHECK (state <> 'purged' or (live_purged_at >= cancel_until and copy_expires_at is not null)),
  CONSTRAINT "lifecycle_witness_ck_17" CHECK (copy_expires_at is null or (live_purged_at is not null and copy_expires_at >= live_purged_at))
);

CREATE TABLE "evidence_link" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id" uuid NOT NULL,
  "event_id" uuid,
  "target_record_id" uuid NOT NULL,
  "category" text,
  "purpose" text NOT NULL,
  "position" integer,
  "field_path" text,
  "expected_revision" bigint,
  "resulting_revision" bigint,
  "content_hash" text,
  "value_snapshot" text,
  "occurrence_date" date,
  "source_operation_id" uuid,
  "projection" text,
  "source_purpose" text,
  "completeness" text,
  "source_cursor" text,
  "prior_record_id" uuid,
  "resulting_record_id" uuid,
  "consumer_record_id" uuid,
  PRIMARY KEY ("id"),
  CONSTRAINT "evidence_link_uq_0" UNIQUE ("id", "tenant_id"),
  CONSTRAINT "evidence_link_ck_0" CHECK (category in ('people', 'meetings', 'tasks', 'ministry', 'wiki', 'activity', 'shared_findings')),
