CREATE TABLE "tenant" (
  "id" uuid NOT NULL,
  "kind" text NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "tenant_ck_0" CHECK (kind in ('account', 'plant', 'organization', 'global')),
  CONSTRAINT "tenant_ck_1" CHECK ((kind = 'global') = (id = '00000000-0000-0000-0000-000000000000'::uuid))
);

CREATE TABLE "record" (
  "id" uuid NOT NULL,
  "kind" text NOT NULL,
  "tenant_id" uuid NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "record_uq_0" UNIQUE ("id", "tenant_id"),
  CONSTRAINT "record_ck_0" CHECK (kind in ('account', 'affiliation', 'article_editor_state', 'article_revision', 'assessment', 'assessment_contributor', 'assessment_fact', 'assignment_feedback', 'attestation', 'commitment', 'communication', 'communication_recipient', 'contact_outcome', 'conversation', 'conversation_entry', 'development_enrollment', 'development_milestone', 'development_program', 'development_program_version', 'development_reading', 'development_stage', 'digest_coverage', 'discovery', 'document', 'document_revision', 'effect', 'enrollment_milestone', 'enrollment_plan', 'feedback', 'feedback_publication', 'file_object', 'finding', 'four_cs', 'generated_document', 'household', 'interview', 'invitation', 'job', 'launch_debrief', 'launch_guest', 'launch_milestone', 'leadership_conversation', 'lifecycle_witness', 'mail', 'mail_attempt', 'mail_request', 'meeting', 'meeting_evaluation', 'meeting_item', 'message_template', 'notice', 'notification_preference', 'obligation', 'operation', 'organization', 'organization_person_removal', 'participation', 'passage', 'person', 'person_merge', 'person_note', 'person_skill', 'phase_transition', 'pipeline_person', 'pipeline_sharing', 'pipeline_stage', 'pipeline_stage_move', 'plant', 'plant_geography', 'platform_grant', 'prompt_dismissal', 'provider_event', 'reader_feedback', 'reading', 'recurrence', 'reference_activation', 'reference_item', 'reference_release', 'reference_version', 'residency_link', 'responsibility', 'review', 'seat', 'sending_goal', 'suppression', 'tag', 'task', 'team', 'team_role', 'team_tenure', 'training_assignment', 'training_credit', 'training_program', 'training_requirement', 'training_version', 'venue', 'wiki_preference')),
