CREATE TABLE "sending_goal" (
  "id" uuid NOT NULL,
  "organization_id" uuid NOT NULL,
  "leaders_target" integer NOT NULL,
  "plants_target" integer NOT NULL,
  "target_year" integer NOT NULL,
  "rationale" text NOT NULL,
  "revision" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "sending_goal_uq_0" UNIQUE ("id", "organization_id"),
  CONSTRAINT "sending_goal_ck_0" CHECK (revision >= 1),
  CONSTRAINT "sending_goal_ck_1" CHECK (leaders_target >= 0),
  CONSTRAINT "sending_goal_ck_2" CHECK (plants_target >= 0),
  CONSTRAINT "sending_goal_ck_3" CHECK (target_year between 1 and 9999)
);

CREATE TABLE "pipeline_stage" (
  "id" uuid NOT NULL,
  "organization_id" uuid NOT NULL,
  "stable_kind" text NOT NULL,
  "label" text NOT NULL,
  "position" integer NOT NULL,
  "removed_at" timestamptz,
  "revision" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "pipeline_stage_uq_0" UNIQUE ("id", "organization_id"),
  CONSTRAINT "pipeline_stage_ck_0" CHECK (revision >= 1),
  CONSTRAINT "pipeline_stage_ck_1" CHECK (stable_kind in ('potential_leader','apprentice','resident','commissioned','not_continuing','other')),
  CONSTRAINT "pipeline_stage_ck_2" CHECK (position >= 0),
  CONSTRAINT "pipeline_stage_ck_3" CHECK (length(btrim(label)) between 1 and 255)
);

CREATE TABLE "pipeline_person" (
  "id" uuid NOT NULL,
  "organization_id" uuid NOT NULL,
  "person_id" uuid NOT NULL,
  "stage_id" uuid NOT NULL,
  "responsible_seat_id" uuid,
  "assessed_on" date,
  "assessor_label" text,
  "revision" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "pipeline_person_uq_0" UNIQUE ("id", "organization_id"),
  CONSTRAINT "pipeline_person_uq_1" UNIQUE ("person_id", "organization_id"),
  CONSTRAINT "pipeline_person_ck_0" CHECK (revision >= 1),
  CONSTRAINT "pipeline_person_ck_1" CHECK ((assessed_on is null) = (assessor_label is null))
);

CREATE TABLE "pipeline_stage_move" (
  "id" uuid NOT NULL,
  "organization_id" uuid NOT NULL,
  "person_id" uuid NOT NULL,
  "from_stage_id" uuid,
  "to_stage_id" uuid NOT NULL,
  "old_label" text,
  "new_label" text NOT NULL,
  "actor_id" uuid,
  "moved_at" timestamptz NOT NULL,
  "reason" text,
  "revision" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "pipeline_stage_move_uq_0" UNIQUE ("id", "organization_id"),
  CONSTRAINT "pipeline_stage_move_ck_0" CHECK (revision >= 1),
  CONSTRAINT "pipeline_stage_move_ck_1" CHECK (length(btrim(reason)) between 1 and 5000)
);

CREATE TABLE "leadership_conversation" (
  "id" uuid NOT NULL,
  "organization_id" uuid NOT NULL,
  "person_id" uuid NOT NULL,
  "staff_account_id" uuid,
  "occurred_at" timestamptz NOT NULL,
  "note" text,
  "revision" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "leadership_conversation_uq_0" UNIQUE ("id", "organization_id"),
  CONSTRAINT "leadership_conversation_ck_0" CHECK (revision >= 1)
);

CREATE TABLE "development_program" (
  "id" uuid NOT NULL,
  "organization_id" uuid NOT NULL,
  "kind" text NOT NULL,
  "name" text NOT NULL,
  "director_seat_id" uuid NOT NULL,
  "current_version_id" uuid,
  "revision" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "development_program_uq_0" UNIQUE ("id", "organization_id"),
  CONSTRAINT "development_program_ck_0" CHECK (revision >= 1),
  CONSTRAINT "development_program_ck_1" CHECK (kind in ('apprenticeship','residency'))
);

CREATE TABLE "development_program_version" (
  "id" uuid NOT NULL,
  "organization_id" uuid NOT NULL,
  "program_id" uuid NOT NULL,
  "version_number" integer NOT NULL,
  "rhythm" text NOT NULL,
  "expected_months" integer NOT NULL,
  "published_at" timestamptz,
  "revision" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "development_program_version_uq_0" UNIQUE ("id", "organization_id"),
  CONSTRAINT "development_program_version_uq_1" UNIQUE ("program_id", "version_number"),
  CONSTRAINT "development_program_version_uq_2" UNIQUE ("id", "program_id", "organization_id"),
  CONSTRAINT "development_program_version_ck_0" CHECK (revision >= 1),
  CONSTRAINT "development_program_version_ck_1" CHECK (version_number >= 1),
  CONSTRAINT "development_program_version_ck_2" CHECK (expected_months > 0)
);

CREATE TABLE "development_stage" (
  "id" uuid NOT NULL,
  "organization_id" uuid NOT NULL,
  "version_id" uuid NOT NULL,
  "label" text NOT NULL,
  "position" integer NOT NULL,
  "min_months" integer NOT NULL,
  "max_months" integer NOT NULL,
  "revision" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "development_stage_uq_0" UNIQUE ("id", "organization_id"),
  CONSTRAINT "development_stage_uq_1" UNIQUE ("id", "version_id", "organization_id"),
  CONSTRAINT "development_stage_ck_0" CHECK (revision >= 1),
  CONSTRAINT "development_stage_ck_1" CHECK (position >= 0),
  CONSTRAINT "development_stage_ck_2" CHECK (min_months >= 0),
  CONSTRAINT "development_stage_ck_3" CHECK (max_months >= min_months)
);

CREATE TABLE "development_milestone" (
  "id" uuid NOT NULL,
  "organization_id" uuid NOT NULL,
  "version_id" uuid NOT NULL,
  "stage_id" uuid NOT NULL,
  "description" text NOT NULL,
  "position" integer NOT NULL,
  "revision" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "development_milestone_uq_0" UNIQUE ("id", "organization_id"),
  CONSTRAINT "development_milestone_uq_1" UNIQUE ("id", "version_id", "organization_id"),
  CONSTRAINT "development_milestone_ck_0" CHECK (revision >= 1),
  CONSTRAINT "development_milestone_ck_1" CHECK (position >= 0)
);

CREATE TABLE "development_reading" (
  "id" uuid NOT NULL,
  "organization_id" uuid NOT NULL,
  "version_id" uuid NOT NULL,
  "article_id" uuid NOT NULL,
  "source_revision_id" uuid NOT NULL,
  "position" integer NOT NULL,
  "revision" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "development_reading_uq_0" UNIQUE ("id", "organization_id"),
  CONSTRAINT "development_reading_ck_0" CHECK (revision >= 1),
  CONSTRAINT "development_reading_ck_1" CHECK (position >= 0)
);

CREATE TABLE "development_enrollment" (
  "id" uuid NOT NULL,
  "organization_id" uuid NOT NULL,
  "person_id" uuid NOT NULL,
  "program_id" uuid NOT NULL,
  "version_id" uuid NOT NULL,
  "cohort_label" text NOT NULL,
  "started_on" date NOT NULL,
  "expected_end_on" date NOT NULL,
  "status" text NOT NULL,
  "current_stage_id" uuid NOT NULL,
  "next_meeting_at" timestamptz,
  "meeting_timezone" text NOT NULL,
  "revision" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "development_enrollment_uq_0" UNIQUE ("id", "organization_id"),
  CONSTRAINT "development_enrollment_uq_1" UNIQUE ("id", "version_id", "organization_id"),
  CONSTRAINT "development_enrollment_uq_3" UNIQUE ("id", "program_id", "organization_id"),
  CONSTRAINT "development_enrollment_ck_0" CHECK (revision >= 1),
  CONSTRAINT "development_enrollment_ck_1" CHECK (status in ('active','completed','withdrawn')),
  CONSTRAINT "development_enrollment_ck_2" CHECK (expected_end_on >= started_on)
);

CREATE UNIQUE INDEX "development_enrollment_uq_2" ON "development_enrollment" ("person_id", "program_id", "organization_id") WHERE status = 'active';

