  "confirmed_by" uuid,
  "confirmed_at" timestamptz,
  "revision" bigint NOT NULL,
  "completion_source" text,
  PRIMARY KEY ("id"),
  CONSTRAINT "enrollment_milestone_uq_0" UNIQUE ("id", "organization_id"),
  CONSTRAINT "enrollment_milestone_uq_1" UNIQUE ("enrollment_id", "milestone_id"),
  CONSTRAINT "enrollment_milestone_ck_0" CHECK (revision >= 1),
  CONSTRAINT "enrollment_milestone_ck_1" CHECK (completed_by is null or completed_at is not null),
  CONSTRAINT "enrollment_milestone_ck_2" CHECK (confirmed_by is null or confirmed_at is not null),
  CONSTRAINT "enrollment_milestone_ck_3" CHECK (confirmed_at is null or completed_at is not null),
  CONSTRAINT "enrollment_milestone_ck_4" CHECK (completion_source in ('resident_self', 'program_leader_recorded')),
  CONSTRAINT "enrollment_milestone_ck_5" CHECK ((completed_at is null) = (completion_source is null)),
  CONSTRAINT "enrollment_milestone_ck_6" CHECK (completion_source <> 'program_leader_recorded' or (completed_at is not null and confirmed_at is not null))
);

CREATE TABLE "assignment_feedback" (
  "id" uuid NOT NULL,
  "organization_id" uuid NOT NULL,
  "enrollment_milestone_id" uuid NOT NULL,
  "author_id" uuid,
  "recorded_at" timestamptz NOT NULL,
  "body" text NOT NULL,
  "revision" bigint NOT NULL,
  "supersedes_id" uuid,
  "withdrawn_at" timestamptz,
  PRIMARY KEY ("id"),
  CONSTRAINT "assignment_feedback_uq_0" UNIQUE ("id", "organization_id"),
  CONSTRAINT "assignment_feedback_ck_0" CHECK (revision >= 1),
  CONSTRAINT "assignment_feedback_ck_1" CHECK (supersedes_id is null or supersedes_id <> id)
);

CREATE TABLE "residency_link" (
  "id" uuid NOT NULL,
  "organization_id" uuid NOT NULL,
  "person_id" uuid NOT NULL,
  "account_id" uuid,
  "affiliation_id" uuid NOT NULL,
  "invitation_id" uuid NOT NULL,
  "accepted_at" timestamptz NOT NULL,
  "ended_at" timestamptz,
  "consent_revision" bigint NOT NULL,
  "share_foundations" boolean NOT NULL DEFAULT false,
  "share_milestones" boolean NOT NULL DEFAULT false,
  "revision" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "residency_link_uq_0" UNIQUE ("id", "organization_id"),
  CONSTRAINT "residency_link_ck_0" CHECK (revision >= 1),
  CONSTRAINT "residency_link_ck_1" CHECK (consent_revision >= 1),
  CONSTRAINT "residency_link_ck_2" CHECK (ended_at is null or not (share_foundations or share_milestones)),
  CONSTRAINT "residency_link_ck_3" CHECK (account_id is not null or ended_at is not null)
);

CREATE UNIQUE INDEX "residency_link_uq_1" ON "residency_link" ("organization_id", "person_id") WHERE ended_at is null;

CREATE UNIQUE INDEX "residency_link_uq_2" ON "residency_link" ("organization_id", "account_id") WHERE ended_at is null and account_id is not null;

CREATE TABLE "pipeline_sharing" (
  "id" uuid NOT NULL,
  "organization_id" uuid NOT NULL,
  "relationship_id" uuid NOT NULL,
  "network_id" uuid NOT NULL,
  "share_pipeline_totals" boolean NOT NULL DEFAULT false,
  "changed_by" uuid,
  "revision" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "pipeline_sharing_uq_0" UNIQUE ("id", "organization_id"),
  CONSTRAINT "pipeline_sharing_uq_1" UNIQUE ("relationship_id"),
  CONSTRAINT "pipeline_sharing_ck_0" CHECK (revision >= 1),
  CONSTRAINT "pipeline_sharing_ck_1" CHECK (network_id <> organization_id)
);

CREATE TABLE "enrollment_plan" (
  "id" uuid NOT NULL,
  "organization_id" uuid NOT NULL,
  "enrollment_id" uuid NOT NULL,
  "program_id" uuid NOT NULL,
  "version_id" uuid NOT NULL,
  "adopted_at" timestamptz NOT NULL,
  "adopted_by" uuid,
  "superseded_at" timestamptz,
  "revision" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "enrollment_plan_uq_0" UNIQUE ("id", "organization_id"),
  CONSTRAINT "enrollment_plan_uq_1" UNIQUE ("enrollment_id", "version_id", "organization_id"),
  CONSTRAINT "enrollment_plan_ck_0" CHECK (revision >= 1),
  CONSTRAINT "enrollment_plan_ck_1" CHECK (superseded_at is null or superseded_at >= adopted_at)
);

CREATE UNIQUE INDEX "enrollment_plan_uq_2" ON "enrollment_plan" ("enrollment_id", "organization_id") WHERE superseded_at is null;

CREATE TABLE "organization_person_removal" (
  "id" uuid NOT NULL,
  "organization_id" uuid NOT NULL,
  "person_record_id" uuid NOT NULL,
  "removed_at" timestamptz NOT NULL,
  "requested_by" uuid,
  "witness_checkpoint" bigint NOT NULL,
  "revision" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "organization_person_removal_uq_0" UNIQUE ("id", "organization_id"),
  CONSTRAINT "organization_person_removal_uq_1" UNIQUE ("person_record_id", "organization_id"),
  CONSTRAINT "organization_person_removal_ck_0" CHECK (revision >= 1),
  CONSTRAINT "organization_person_removal_ck_1" CHECK (witness_checkpoint >= 1)
);

