CREATE FUNCTION "account_bind_record"() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $$
DECLARE actual_owner uuid;
BEGIN
  actual_owner := NEW.id;
  INSERT INTO tenant(id,kind) VALUES (NEW.id,'account') ON CONFLICT DO NOTHING; IF NOT EXISTS(SELECT FROM tenant WHERE id=NEW.id AND kind='account') THEN RAISE EXCEPTION 'root_kind_mismatch' USING ERRCODE='23514'; END IF;
  IF TG_OP='UPDATE' AND NEW.id <> OLD.id THEN RAISE EXCEPTION 'immutable_record_id' USING ERRCODE='23514'; END IF;
  INSERT INTO record(id,kind,tenant_id) VALUES (NEW.id,'account',actual_owner) ON CONFLICT DO NOTHING;
  PERFORM 1 FROM record WHERE id=NEW.id AND kind='account' AND tenant_id=actual_owner FOR KEY SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'record_subtype_owner_mismatch' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER bind_record AFTER INSERT OR UPDATE ON "account" FOR EACH ROW EXECUTE FUNCTION "account_bind_record"();

